-- STAGE -- custom beginning_of_all_times=1800-01-01 in unknown ghost row

WITH derived_columns_cte AS (SELECT *, CURRENT_TIMESTAMP() AS "ldts", 'SYS' AS "rsrc" FROM (SELECT * FROM "raw.orders") AS _src) SELECT *, NULLIF(LOWER(MD5(NULLIF(CAST(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(REGEXP_REPLACE(UPPER(CONCAT(COALESCE(CONCAT('\"', REPLACE(REPLACE(REPLACE(TRIM(CAST("order_id" AS VARCHAR(4000))), '\\', '\\\\'), '"', '\"'), '^^', '--'), '\"'), '^^'))), CHR(9), ''), CHR(10), ''), CHR(11), ''), CHR(13), '') AS VARCHAR(4000)), '^^'))), '00000000000000000000000000000000') AS "hk_order" FROM "derived_columns_cte" UNION ALL SELECT '00000000000000000000000000000000' AS "hk_order", '1800-01-01' AS "ldts", 'SYSTEM' AS "rsrc" UNION ALL SELECT 'ffffffffffffffffffffffffffffffff' AS "hk_order", '9999-12-31' AS "ldts", 'ERROR' AS "rsrc"
